import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p46_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor avg_pool3d_forward(torch::Tensor x, int64_t kernel_size, int64_t stride, int64_t padding);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("avg_pool3d_forward", &avg_pool3d_forward, "avg_pool3d_forward");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define COARSEN 4

static __device__ __forceinline__ int ceil_div_dev(int a, int b) {
    return (a + b - 1) / b;
}

__global__ void avg_pool3d_coarsened_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int D, int H, int W,
    int D_out, int H_out, int W_out,
    int kernel_size, int stride, int padding
) {
    // blockIdx.y encodes flat index over (n, c, od, oh)
    // blockIdx.x encodes coarsened W tile
    int flat_row = blockIdx.y;
    int oh = flat_row % H_out; flat_row /= H_out;
    int od = flat_row % D_out; flat_row /= D_out;
    int c  = flat_row % C;     flat_row /= C;
    int n  = flat_row;

    if (n >= N) return;

    int ow_base = (blockIdx.x * blockDim.x + threadIdx.x) * COARSEN;

    int id_start = od * stride - padding;
    int ih_start = oh * stride - padding;

    float accum[COARSEN];
    #pragma unroll
    for (int i = 0; i < COARSEN; i++) accum[i] = 0.0f;

    int iw_start[COARSEN];
    #pragma unroll
    for (int i = 0; i < COARSEN; i++) {
        iw_start[i] = (ow_base + i) * stride - padding;
    }

    // Input base pointer for this (n, c)
    const float* inp = input + ((int64_t)n * C + c) * ((int64_t)D * H * W);

    #pragma unroll
    for (int kd = 0; kd < 3; kd++) {
        int id = id_start + kd;
        if (id < 0 || id >= D) continue;
        #pragma unroll
        for (int kh = 0; kh < 3; kh++) {
            int ih = ih_start + kh;
            if (ih < 0 || ih >= H) continue;
            int row_offset = (id * H + ih) * W;
            #pragma unroll
            for (int kw = 0; kw < 3; kw++) {
                #pragma unroll
                for (int i = 0; i < COARSEN; i++) {
                    int ow = ow_base + i;
                    if (ow >= W_out) continue;
                    int iw = iw_start[i] + kw;
                    if (iw >= 0 && iw < W) {
                        accum[i] += __ldg(inp + row_offset + iw);
                    }
                }
            }
        }
    }

    float inv_count = 1.0f / (float)(kernel_size * kernel_size * kernel_size);
    int64_t out_base = ((int64_t)n * C + c) * ((int64_t)D_out * H_out * W_out)
                       + ((int64_t)od * H_out + oh) * W_out;

    #pragma unroll
    for (int i = 0; i < COARSEN; i++) {
        int ow = ow_base + i;
        if (ow < W_out) {
            output[out_base + ow] = accum[i] * inv_count;
        }
    }
}

torch::Tensor avg_pool3d_forward(torch::Tensor x, int64_t kernel_size, int64_t stride, int64_t padding) {
    // Fallback for unsupported configs
    if (!x.is_cuda() || x.scalar_type() != at::kFloat ||
        kernel_size != 3 || stride != 2 || padding != 1) {
        return at::avg_pool3d(
            x,
            {kernel_size, kernel_size, kernel_size},
            {stride, stride, stride},
            {padding, padding, padding},
            false, true, c10::nullopt
        );
    }

    x = x.contiguous();
    int N = x.size(0), C = x.size(1);
    int D = x.size(2), H = x.size(3), W = x.size(4);

    int D_out = (D + 2*padding - kernel_size) / stride + 1;
    int H_out = (H + 2*padding - kernel_size) / stride + 1;
    int W_out = (W + 2*padding - kernel_size) / stride + 1;

    auto output = torch::empty({N, C, D_out, H_out, W_out}, x.options());

    int block_x = 128;
    int grid_x = (W_out + block_x * COARSEN - 1) / (block_x * COARSEN);
    int grid_y = N * C * D_out * H_out;

    dim3 grid(grid_x, grid_y);
    dim3 block(block_x);

    avg_pool3d_coarsened_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        D_out, H_out, W_out,
        (int)kernel_size, (int)stride, (int)padding
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs 3D Average Pooling.
        """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the Average Pooling layer.

                Args:
                    kernel_size (int): Size of the kernel to apply pooling.
                    stride (int, optional): Stride of the pooling operation. Defaults to None, which uses the kernel size.
                    padding (int, optional): Padding to apply before pooling. Defaults to 0.
                """
        self.avg_pool = nn.AvgPool3d(kernel_size=kernel_size, stride=stride, padding=padding)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Average Pooling to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, channels, depth, height, width).

                Returns:
                    torch.Tensor: Output tensor with Average Pooling applied, shape depends on kernel_size, stride and padding.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda:
            ks = self.avg_pool.kernel_size if isinstance(self.avg_pool.kernel_size, int) else self.avg_pool.kernel_size[0]
            st = self.avg_pool.stride if isinstance(self.avg_pool.stride, int) else self.avg_pool.stride[0]
            pd = self.avg_pool.padding if isinstance(self.avg_pool.padding, int) else self.avg_pool.padding[0]
            return _stark_get_extension().avg_pool3d_forward(x.contiguous(), ks, st, pd)
