    const float* inp = input + ((int64_t)n * C + c) * ((int64_t)D * H * W);

    #pragma unroll
    for (int kd = 0; kd < 3; kd++) {
        int id = id_start + kd;
        if (id < 0 || id >= D) continue;
        #pragma unroll
        for (int kh = 0; kh < 3; kh++) {
            int ih = ih_start + kh;
            if (ih < 0 || ih >= H) continue;
            int row_offset = (id * H + ih) * W;
            #pragma unroll
            for (int kw = 0; kw < 3; kw++) {
                #pragma unroll
                for (int i = 0; i < COARSEN; i++) {
                    int ow = ow_base + i;
                    if (ow >= W_out) continue;
                    int iw = iw_base + i * stride + kw;
                    if (iw >= 0 && iw < W) {
                        accum[i] += __ldg(inp + row_offset + iw);
                    }
                }
            }
        }
    }

    float inv_count = 1.0f / (float)(kernel_size * kernel_size * kernel_size);
    int64_t out_base = ((int64_t)n * C + c) * ((int64_t)D_out * H_out * W_out)
                       + ((int64_t)od * H_out + oh) * W_out;

    #pragma unroll
    for (int i = 0; i < COARSEN; i++) {
        int ow = ow_base + i;
        if (ow < W_out) {
            output[out_base + ow] = accum[i] * inv_count;
        }
    }
}

torch::Tensor avg_pool3d_forward(torch::Tensor x, int64_t kernel_size, int64_t stride, int64_t padding) {
    if (!x.is_cuda() || x.scalar_type() != at::kFloat ||
        kernel_size != 3 || stride != 2 || padding != 1) {
