    int N = x.size(0), C = x.size(1);
    int D = x.size(2), H = x.size(3), W = x.size(4);

    int D_out = (D + 2*(int)padding - (int)kernel_size) / (int)stride + 1;
    int H_out = (H + 2*(int)padding - (int)kernel_size) / (int)stride + 1;
    int W_out = (W + 2*(int)padding - (int)kernel_size) / (int)stride + 1;

    auto output = torch::empty({N, C, D_out, H_out, W_out}, x.options());

    // Use shared-memory tiled kernel
    dim3 block(W_TILE, H_TILE, 1);  // 128 threads
    dim3 grid(
        (W_out + W_TILE - 1) / W_TILE,
        (H_out + H_TILE - 1) / H_TILE,
        N * C * D_out
    );

    avg_pool3d_smem_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        D_out, H_out, W_out
    );

    return output;
}
